function validate([radius, xCenter, yCenter, x1, y1, x2, y2]) {
  const all = [radius, xCenter, yCenter, x1, y1, x2, y2];
  if (!all.every(Number.isInteger)) return 'All values are integers.';
  if (radius < 1 || radius > 2000) return 'radius is between 1 and 2000.';
  if ([xCenter, yCenter, x1, y1, x2, y2].some(v => v < -10000 || v > 10000)) return 'Coordinates are between -10^4 and 10^4.';
  if (x1 >= x2 || y1 >= y2) return 'Need x1 < x2 and y1 < y2.';
  return null;
}

