function checkOverlap(radius, xCenter, yCenter, x1, y1, x2, y2) {
  // All coordinates are integers, so the nearest rectangle point is a lattice point.
  // Scan each integer column the two shapes share and test whether their vertical ranges meet.
  const from = Math.max(x1, xCenter - radius), to = Math.min(x2, xCenter + radius);
  for (let x = from; x <= to; x++) {
    const rest = radius * radius - (x - xCenter) * (x - xCenter);
    let reach = Math.floor(Math.sqrt(rest));
    while (reach * reach > rest) reach--;
    while ((reach + 1) * (reach + 1) <= rest) reach++;
    if (yCenter - reach <= y2 && y1 <= yCenter + reach) return true;
  }
  return false;
}

