function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const span = size === 'large' ? 10000 : 8;
  const radius = size === 'large' ? int(1, 2000) : int(1, 5);
  const clamp = v => Math.max(-span, Math.min(span, v));
  let x1 = int(-span, span - 1), y1 = int(-span, span - 1);
  let x2 = int(x1 + 1, Math.min(span, x1 + (size === 'large' ? 3000 : 6)));
  let y2 = int(y1 + 1, Math.min(span, y1 + (size === 'large' ? 3000 : 6)));
  // Put the centre near the rectangle, about one radius away, so both answers are common.
  const angle = rand() * 2 * Math.PI, away = radius * (0.5 + rand());
  const anchorX = rand() < 0.5 ? x1 : x2, anchorY = rand() < 0.5 ? y1 : y2;
  const xCenter = clamp(Math.round(anchorX + Math.cos(angle) * away));
  const yCenter = clamp(Math.round(anchorY + Math.sin(angle) * away));
  return [radius, xCenter, yCenter, x1, y1, x2, y2];
}
